def _process_streaming_chunk(chunk):
    """Extract content, tool call deltas, finish reasons and usage from a chunk."""
    if not chunk.choices:
        return None, [], [], None

    choice = chunk.choices[0]
    delta = choice.delta
    content = delta.content if hasattr(delta, "content") else None

    tool_calls_delta = []
    if hasattr(delta, "tool_calls") and delta.tool_calls:
        tool_calls_delta = list(delta.tool_calls)

    finish_reasons = []
    if choice.finish_reason:
        finish_reasons = [choice.finish_reason]

    # Extract usage from x_groq if present in the final chunk
    usage = None
    if hasattr(chunk, "x_groq") and chunk.x_groq and chunk.x_groq.usage:
        usage = chunk.x_groq.usage

    return content, tool_calls_delta, finish_reasons, usage


